CREATE TABLE "checklist_template" ("id" uuid PRIMARY KEY,"projectId" uuid NOT NULL,"code" varchar(50) NOT NULL,"name" varchar(250) NOT NULL,"category" varchar(20) NOT NULL,"version" integer NOT NULL,"status" varchar(20) NOT NULL DEFAULT 'DRAFT',"publishedAt" timestamptz,"createdBy" uuid NOT NULL,"source" varchar(20) NOT NULL DEFAULT 'WEB',UNIQUE("projectId","code","version"));
CREATE TABLE "checklist_section" ("id" uuid PRIMARY KEY,"templateId" uuid NOT NULL REFERENCES "checklist_template"("id") ON DELETE CASCADE,"number" varchar(30) NOT NULL,"title" varchar(300) NOT NULL,"order" integer NOT NULL,UNIQUE("templateId","number"));
CREATE TABLE "checklist_item" ("id" uuid PRIMARY KEY,"sectionId" uuid NOT NULL REFERENCES "checklist_section"("id") ON DELETE CASCADE,"number" varchar(30) NOT NULL,"requirementText" text NOT NULL,"severity" varchar(20) NOT NULL,"responseType" varchar(20) NOT NULL,"requiresPhoto" boolean NOT NULL DEFAULT false,"minPhotos" integer NOT NULL DEFAULT 0,"maxPhotos" integer NOT NULL DEFAULT 0,"allowsNa" boolean NOT NULL DEFAULT false,"isRequired" boolean NOT NULL DEFAULT true,"guidanceText" text,"order" integer NOT NULL,UNIQUE("sectionId","number"));
CREATE TABLE "submission" ("id" uuid PRIMARY KEY,"taskId" uuid NOT NULL,"siteId" uuid NOT NULL,"projectId" uuid NOT NULL,"templateId" uuid NOT NULL REFERENCES "checklist_template"("id"),"templateVersion" integer NOT NULL,"attemptNo" integer NOT NULL,"status" varchar(30) NOT NULL,"overallVerdict" varchar(10),"submittedBy" uuid NOT NULL,"submittedAt" timestamptz,"reviewedBy" uuid,"reviewedAt" timestamptz,"reviewComment" text,"integrityHash" varchar(64) NOT NULL,"idempotencyKey" varchar(255) NOT NULL UNIQUE,"deviceId" varchar(255),UNIQUE("taskId","attemptNo"));
CREATE TABLE "item_response" ("id" uuid PRIMARY KEY,"submissionId" uuid NOT NULL REFERENCES "submission"("id") ON DELETE CASCADE,"itemId" uuid NOT NULL REFERENCES "checklist_item"("id"),"selfCheckResult" varchar(10) NOT NULL,"selfCheckDescription" text,"textValue" text,"numberValue" decimal(18,4),"booleanValue" boolean,"selectValue" varchar(500),"reviewResult" varchar(20) NOT NULL DEFAULT 'PENDING',"reviewDescription" text,"reviewedBy" uuid,"reviewedAt" timestamptz,UNIQUE("submissionId","itemId"));
CREATE TABLE "item_photo" ("id" uuid PRIMARY KEY,"itemResponseId" uuid NOT NULL REFERENCES "item_response"("id") ON DELETE CASCADE,"mediaId" uuid NOT NULL,"sequence" integer NOT NULL,UNIQUE("itemResponseId","sequence")); CREATE TABLE "review_decision" ("id" uuid PRIMARY KEY,"submissionId" uuid NOT NULL REFERENCES "submission"("id") ON DELETE CASCADE,"reviewerId" uuid NOT NULL,"decision" varchar(30) NOT NULL,"comment" text,"decidedAt" timestamptz NOT NULL DEFAULT now());
